import 'package:audioplayers/audioplayers.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

/// Ring bell at the start of the clock and at the end of a match.
abstract interface class Bell {
  void ring();
}

final bellProvider = Provider<Bell>((ref) {
  final bell = _AudioBell();
  ref.onDispose(bell.dispose);
  return bell;
});

class _AudioBell implements Bell {
  final _player = AudioPlayer();

  // assets/sounds/bell.wav, generated by tool/make_bell.py.
  @override
  void ring() {
    _player.stop().then((_) => _player.play(AssetSource('sounds/bell.wav')));
  }

  void dispose() => _player.dispose();
}
